<?php

namespace App\Enums;

enum BarcodeType: string
{
    /** Printed by the manufacturer (EAN-13/EAN-8/UPC-A/GTIN-14); checksum validated. */
    case Manufacturer = 'manufacturer';

    /** Generated by this system for unlabelled goods (restricted-circulation EAN-13, prefix 20-29). */
    case Internal = 'internal';

    /** A packaging barcode (e.g. carton GTIN) mapped to a non-base unit. */
    case Packaging = 'packaging';

    public function label(): string
    {
        return match ($this) {
            self::Manufacturer => 'Manufacturer',
            self::Internal => 'Internal',
            self::Packaging => 'Packaging',
        };
    }
}
